using SharpTestBench;
/// <summary>Byte-lane isolation, synchronous read policy and reset precedence.</summary>
public static partial class Entry
{
 [SimTest] public static async Task R053_ResetClearsEveryWordAndOutput(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,0,0,0,false,true);for(int i=0;i<8;i++)Check(Read(c,"b_obs"+i)==0,"all reset words visible");}
 [SimTest] public static async Task R054_FullWordWriteAtEveryAddress(TestContext c){await Reset(c);var m=new BankModel();for(int i=0;i<8;i++)await m.Step(c,i,0x1357^(i*0x1111),3,true,false);for(int i=0;i<8;i++)await m.Step(c,i,0,0,false,true);}
 [SimTest] public static async Task R055_LowByteWritePreservesHighLane(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,3,0xabcd,3,true,false);await m.Step(c,3,0x1234,1,true,true);await m.Step(c,3,0,0,false,true);Check(Read(c,"b_result")==0xab34,"literal low-lane preservation");}
 [SimTest] public static async Task R056_HighByteWritePreservesLowLane(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,4,0xabcd,3,true,false);await m.Step(c,4,0x1234,2,true,true);await m.Step(c,4,0,0,false,true);Check(Read(c,"b_result")==0x12cd,"literal high-lane preservation");}
 [SimTest] public static async Task R057_ZeroMaskCannotChangeStoredWord(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,2,0xcafe,3,true,false);await m.Step(c,2,0,0,true,true);await m.Step(c,2,0,0,false,true);}
 [SimTest] public static async Task R058_WriteDisableDominatesAllByteEnables(TestContext c){await Reset(c);var m=new BankModel();for(int mask=0;mask<4;mask++)await m.Step(c,1,0xffff,mask,false,true);Check(Read(c,"b_result")==0,"disabled writes never admitted");}
 [SimTest] public static async Task R059_ReadDisableHoldsPriorOutput(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,0,0x1234,3,true,false);await m.Step(c,0,0,0,false,true);for(int i=0;i<8;i++)await m.Step(c,i,0xffff,3,true,false);Check(Read(c,"b_result")==0x1234,"read output hold across writes");}
 [SimTest] public static async Task R060_ReadIsSynchronousRatherThanCombinational(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,5,0x5678,3,true,false);Put(c,"b_address",5);Put(c,"b_read",1);await SharpTestBench.Triggers.Timer(1);Check(Read(c,"b_result")==0,"address/read-enable alone cannot update output");await m.Step(c,5,0,0,false,true);}
 [SimTest] public static async Task R061_SameAddressCollisionReadsOldWord(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,6,0x1111,3,true,false);await m.Step(c,6,0x2222,3,true,true);Check(Read(c,"b_result")==0x1111,"literal old-data collision");await m.Step(c,6,0,0,false,true);Check(Read(c,"b_result")==0x2222,"new data visible on later read");}
 [SimTest] public static async Task R062_WritingOneAddressCannotModifyNeighbors(TestContext c){await Reset(c);var m=new BankModel();for(int i=0;i<8;i++)await m.Step(c,i,0x1000+i,3,true,false);for(int i=7;i>=0;i--)await m.Step(c,i,0xdead,3,true,false);}
 [SimTest] public static async Task R063_ResetDominatesConcurrentReadAndWrite(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,2,0x2468,3,true,false);await m.Step(c,7,0x1357,3,true,false);await m.Step(c,7,0,0,false,true);Check(Read(c,"b_result")==0x1357&&Read(c,"b_obs7")==0x1357&&Read(c,"b_obs2")==0x2468,"nonzero reset/read/write precondition");await m.Step(c,7,0xffff,3,true,true,reset:true);Check(Read(c,"b_result")==0,"reset dominates a nonzero concurrent read");for(int i=0;i<8;i++)Check(Read(c,"b_obs"+i)==0,"reset clears every word and suppresses the concurrent write");}
 [SimTest] public static async Task R064_ResetClearsHeldReadOutput(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,1,0xabcd,3,true,false);await m.Step(c,1,0,0,false,true);await m.Step(c,1,0,0,false,false,reset:true);Check(Read(c,"b_result")==0,"reset clears otherwise held output");}
 [SimTest] public static async Task R065_AlternatingLaneUpdatesComposeOneWord(TestContext c){await Reset(c);var m=new BankModel();for(int i=0;i<16;i++)await m.Step(c,0,(i<<8)|(15-i),i%2==0?1:2,true,true);await m.Step(c,0,0,0,false,true);Check(Read(c,"b_result")==0x0f01,"literal alternating-lane composition");}
 [SimTest] public static async Task R066_SeededMixedBankOperations(TestContext c){await Reset(c);var m=new BankModel();for(int i=0;i<256;i++)await m.Step(c,c.Random.Next(8),c.Random.Next(65536),c.Random.Next(4),c.Random.Next(3)!=0,c.Random.Next(3)!=0,reset:i%61==60);}
 [SimTest] public static async Task R067_FirstAndLastAddressesDoNotAlias(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,0,0x00ff,3,true,false);await m.Step(c,7,0xff00,3,true,false);await m.Step(c,0,0,0,false,true);Check(Read(c,"b_result")==0xff,"address zero boundary");await m.Step(c,7,0,0,false,true);Check(Read(c,"b_result")==0xff00,"address seven boundary");}
 [SimTest] public static async Task R068_ZeroAndOnesLaneDataCanOverwriteEveryBit(TestContext c){await Reset(c);var m=new BankModel();for(int i=0;i<8;i++){await m.Step(c,i,0xffff,3,true,false);await m.Step(c,i,0,1,true,false);await m.Step(c,i,0,2,true,true);await m.Step(c,i,0,0,false,true);}}
 [SimTest] public static async Task R069_OracleRejectsSwappedByteLanes(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,2,0xabcd,3,true,false);await m.Step(c,2,0,0,false,true);await NativeFault(c,"b_result",0xcdab,()=>m.Observe(c));}
 [SimTest] public static async Task R070_AfterNegativeProbeLaterWriteAndReadRecover(TestContext c){await Reset(c);var m=new BankModel();await m.Step(c,0,0x1234,3,true,false);await NativeFault(c,"b_result",0x3412,()=>m.Observe(c));await m.Step(c,0,0x5678,3,true,false);await m.Step(c,0,0,0,false,true);Check(Read(c,"b_result")==0x5678,"subsequent transaction remains usable");}
}
